          import org.apache.log4j.Logger;

          import sailpoint.object.Identity;

          Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
          if (logger.isTraceEnabled()) {
          logger.trace("Alpha-Form-Immediate-Terminating-Users -> Entered to displayName Field (UserDisplayDetails Section)!!!");
          }
          String DisplayName = null;
          Identity identityObject = context.getObjectByName(Identity.class, terminateIdentity);
          logger.debug("Alpha-Form-Immediate-Terminating-Users - displayName Field (UserDisplayDetails Section) -> DisplayName : "+identityObject.getDisplayName());
          DisplayName = identityObject.getDisplayName();
          if (identityObject != null) {
          context.decache(identityObject);
          }
          return DisplayName;

